package com.yonlab.vision;

import android.content.Context;
import android.graphics.Bitmap;
import org.tensorflow.lite.*;
import java.io.*;
import java.nio.*;
import java.util.*;

/** NanoDet-Plus DFL and EfficientDet-Lite1, both mapped to the original sparse COCO IDs. */
final class AddedObjectEngine implements AutoCloseable {
 final String sha256;private AddedVisionOnnx nano;private Interpreter efficient;private final List<String> labels=new ArrayList<>(),sparse=new ArrayList<>();
 private boolean closed;private int side,count;private ByteBuffer input;private int[] pixels;private float[][][] boxes;private float[][] classes,scores;private final float[] number=new float[1];private final Map<Integer,Object> outputs=new HashMap<>();
 AddedObjectEngine(Context c,String id)throws Exception{
  sha256=AddedVisionModels.sha(id);OneObjectEngine.read(c,"one/models/coco80-labels.txt",labels);OneObjectEngine.read(c,"models/labelmap.txt",sparse);if(labels.size()!=80)throw new IOException("COCO 분류표를 확인하세요");
  if("nanodet-plus".equals(id)){nano=new AddedVisionOnnx(c,id);return;}
  if(!"efficientdet-lite1".equals(id))throw new IllegalArgumentException("객체 모델을 선택하세요");
  Interpreter initialized=new Interpreter(ModelPlusAssets.map(c,AddedVisionModels.asset(id),sha256,16L*1024*1024),new Interpreter.Options().setNumThreads(OneExecutionSettings.threads(c)));
  try{initialized.allocateTensors();if(initialized.getInputTensorCount()!=1||initialized.getOutputTensorCount()!=4)throw new IOException("객체 모델 입출력을 확인하세요");DataType[] types=new DataType[4];int[][] shapes=new int[4][];for(int n=0;n<4;n++){types[n]=initialized.getOutputTensor(n).dataType();shapes[n]=initialized.getOutputTensor(n).shape();}count=ObjectEngine.validateContract(initialized.getInputTensor(0).dataType(),initialized.getInputTensor(0).shape(),types,shapes);side=initialized.getInputTensor(0).shape()[1];input=ByteBuffer.allocateDirect(side*side*3).order(ByteOrder.nativeOrder());pixels=new int[side*side];boxes=new float[1][count][4];classes=new float[1][count];scores=new float[1][count];outputs.put(0,boxes);outputs.put(1,classes);outputs.put(2,scores);outputs.put(3,number);efficient=initialized;}catch(Exception|LinkageError|OutOfMemoryError e){initialized.close();throw e;}
 }
 synchronized List<Observations.Detection> analyze(Bitmap image,float threshold)throws Exception{
  if(closed)throw new IOException("모델이 종료되었습니다");if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("분석 취소");if(image==null||image.isRecycled()||(long)image.getWidth()*image.getHeight()>16000000||!Float.isFinite(threshold)||threshold<0||threshold>1)throw new IOException("사진과 검출 설정을 확인하세요");
  if(nano!=null)return nano.run(image,r->{List<Candidate> all=new ArrayList<>();String[] cls={"792","814","836"},reg={"795","817","839"};int[] strides={8,16,32};for(int level=0;level<3;level++){Object a=AddedVisionOnnx.output(r,cls[level]),b=AddedVisionOnnx.output(r,reg[level]);if(!(a instanceof float[][][])||!(b instanceof float[][][]))throw new IOException("NanoDet 출력 형식");float[][] scores=((float[][][])a)[0],boxes=((float[][][])b)[0];int stride=strides[level],grid=416/stride;if(scores.length!=grid*grid||boxes.length!=scores.length)throw new IOException("NanoDet 출력 크기");List<Integer> selected=new ArrayList<>();for(int n=0;n<scores.length;n++){if(scores[n].length!=80||boxes[n].length!=32)throw new IOException("NanoDet 분류 크기");float max=0;for(float v:scores[n])if(Float.isFinite(v))max=Math.max(max,v);if(max>=threshold&&max<=1)selected.add(n);}selected.sort((x,y)->Float.compare(max(scores[y]),max(scores[x])));for(int p=0;p<Math.min(1000,selected.size());p++){int n=selected.get(p),category=0;for(int k=1;k<80;k++)if(scores[n][k]>scores[n][category])category=k;float score=scores[n][category];if(!Float.isFinite(score)||score<threshold||score>1)continue;float[] distance=new float[4];boolean valid=true;for(int edge=0;edge<4;edge++){float maximum=-Float.MAX_VALUE;for(int k=0;k<8;k++){float value=boxes[n][edge*8+k];valid&=Float.isFinite(value);maximum=Math.max(maximum,value);}double sum=0,weighted=0;for(int k=0;k<8;k++){double exp=Math.exp(boxes[n][edge*8+k]-maximum);sum+=exp;weighted+=k*exp;}distance[edge]=(float)(weighted/sum)*stride;}if(!valid)continue;float cx=(n%grid)*stride+.5f*(stride-1),cy=(n/grid)*stride+.5f*(stride-1);all.add(new Candidate(category,score,Math.max(0,cx-distance[0]),Math.max(0,cy-distance[1]),Math.min(416,cx+distance[2]),Math.min(416,cy+distance[3])));}}
   all.sort((x,y)->Float.compare(y.score,x.score));List<Candidate> kept=new ArrayList<>();for(Candidate item:all){boolean suppressed=false;for(Candidate prior:kept)if(item.category==prior.category&&iou(item,prior)>.6f){suppressed=true;break;}if(!suppressed){kept.add(item);if(kept.size()>=100)break;}}List<Observations.Detection> out=new ArrayList<>();float scale=Math.min(416f/image.getWidth(),416f/image.getHeight());int rw=Math.max(1,(int)(image.getWidth()*scale)),rh=Math.max(1,(int)(image.getHeight()*scale)),left=(416-rw)/2,top=(416-rh)/2;for(Candidate item:kept){float l=clamp((item.l-left)/rw),t=clamp((item.t-top)/rh),right=clamp((item.r-left)/rw),bottom=clamp((item.b-top)/rh);if(right<=l||bottom<=t)continue;String label=labels.get(item.category);int category=sparse.indexOf(label)-1;if(category>=0)out.add(new Observations.Detection(category,label,item.score,l,t,right,bottom));}return out;});
  Bitmap resized=Bitmap.createScaledBitmap(image,side,side,true);try{resized.getPixels(pixels,0,side,0,0,side,side);}finally{if(resized!=image)resized.recycle();}input.clear();for(int p:pixels){input.put((byte)(p>>>16));input.put((byte)(p>>>8));input.put((byte)p);}input.rewind();efficient.runForMultipleInputsOutputs(new Object[]{input},outputs);List<Observations.Detection> out=new ArrayList<>();int n=Float.isFinite(number[0])?Math.min(count,Math.max(0,Math.round(number[0]))):0;for(int i=0;i<n;i++){int category=Math.round(classes[0][i]);float score=scores[0][i];float[] b=boxes[0][i];if(!Float.isFinite(score)||!Float.isFinite(classes[0][i])||score<threshold||score>1||category<0||category+1>=sparse.size())continue;float t=clamp(b[0]),l=clamp(b[1]),bottom=clamp(b[2]),right=clamp(b[3]);if(!Float.isFinite(t+l+bottom+right)||l>=right||t>=bottom)continue;String label=sparse.get(category+1);if(!"???".equals(label))out.add(new Observations.Detection(category,label,score,l,t,right,bottom));}return out;
 }
 private static float max(float[] a){float v=0;for(float f:a)if(Float.isFinite(f))v=Math.max(v,f);return v;}
 private static float clamp(float n){return Math.max(0,Math.min(1,n));}
 private static final class Candidate{final int category;final float score,l,t,r,b;Candidate(int c,float s,float l,float t,float r,float b){category=c;score=s;this.l=l;this.t=t;this.r=r;this.b=b;}}
 private static float iou(Candidate a,Candidate b){float area=Math.max(0,Math.min(a.r,b.r)-Math.max(a.l,b.l))*Math.max(0,Math.min(a.b,b.b)-Math.max(a.t,b.t));float sum=(a.r-a.l)*(a.b-a.t)+(b.r-b.l)*(b.b-b.t)-area;return sum>0?area/sum:0;}
 public synchronized void close(){if(closed)return;closed=true;if(nano!=null)nano.close();if(efficient!=null)efficient.close();}
}
